<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3';
import AdminLayout from '@/Layouts/AdminLayout.vue';
const props = defineProps({ application: Object, statusLabels: Object });
const form = useForm({ status: '', admin_note: '' });
const decide = (status) => { form.status = status; form.put(route('admin.applications.update', props.application.id)); };
</script>
<template><Head title="Detail Permohonan" /><AdminLayout><Link :href="route('admin.applications.index')" class="text-sm font-semibold text-aski-700">← Kembali</Link><div class="mt-5 flex flex-wrap justify-between gap-3"><div><p class="text-sm font-semibold text-aski-700">PERMOHONAN #{{ application.id }}</p><h1 class="mt-1 text-3xl font-bold text-aski-900">{{ application.user.name }}</h1><p class="text-slate-500">{{ application.user.email }}</p></div><span class="rounded-full bg-aski-100 px-3 py-1 text-sm font-semibold text-aski-800">{{ statusLabels[application.status] }}</span></div><div class="mt-7 grid max-w-4xl gap-6 lg:grid-cols-2"><section class="card p-6"><h2 class="font-bold text-aski-900">Profil Pemohon</h2><dl class="mt-4 space-y-3 text-sm"><div><dt class="text-slate-500">Tipe</dt><dd>{{ application.user.member_profile?.account_type === 'institution' ? 'Institusi' : 'Individu' }}</dd></div><div><dt class="text-slate-500">Telepon</dt><dd>{{ application.user.member_profile?.phone }}</dd></div><div><dt class="text-slate-500">Alamat</dt><dd>{{ application.user.member_profile?.address }}</dd></div></dl></section><section class="card p-6"><h2 class="font-bold text-aski-900">Keputusan Admin</h2><div v-if="application.status === 'submitted'" class="mt-4"><textarea v-model="form.admin_note" rows="4" placeholder="Catatan untuk Member (wajib untuk revisi/penolakan)" class="w-full rounded-lg border-slate-300 focus:border-aski-500 focus:ring-aski-500"></textarea><p class="text-xs text-red-600">{{ form.errors.admin_note }}</p><div class="mt-4 flex flex-wrap gap-2"><button class="btn-primary" @click="decide('approved_waiting_payment')">Setujui</button><button class="rounded-lg bg-gold-400 px-4 py-2 text-sm font-semibold text-aski-900" @click="decide('revision')">Minta Revisi</button><button class="rounded-lg bg-red-600 px-4 py-2 text-sm font-semibold text-white" @click="decide('rejected')">Tolak</button></div></div><p v-else class="mt-4 text-sm text-slate-600">Permohonan ini telah diproses.</p></section></div><section class="card mt-6 max-w-4xl p-6"><h2 class="font-bold text-aski-900">Riwayat Status</h2><ol class="mt-4 space-y-3 text-sm"><li v-for="history in application.histories" :key="history.id" class="border-l-2 border-gold-400 pl-4"><b>{{ statusLabels[history.status] }}</b><p class="text-slate-500">{{ new Date(history.created_at).toLocaleString('id-ID') }}<span v-if="history.changed_by"> · {{ history.changed_by.name }}</span></p><p v-if="history.note">{{ history.note }}</p></li></ol></section></AdminLayout></template>
